from datetime import datetime, date, time, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from zoneinfo import ZoneInfo

inp = Path('/app/input')
out = Path('/app')

order_date = date(2026, 9, 25)
order_dt = datetime(2026, 9, 25, 14, 40, tzinfo=ZoneInfo('America/Chicago'))
delivery_city = 'Phenix City'
delivery_state = 'AL'
delivery_fee = Decimal('9.99')
supplied_length_ft = Decimal('10')
max_length_ft = Decimal('15')

# Catalogue
catalogue = {}
with open(inp / 'cord_catalogue.csv', newline='') as f:
    for row in csv.DictReader(f):
        catalogue[row['sku']] = row

# Offers, keyed by offer_id per submission format
offers = {}
with open(inp / 'same_day_offers.csv', newline='') as f:
    for row in csv.DictReader(f):
        offers[row['offer_id']] = row
offer_ids = sorted(offers)

# Store directory: latest effective row on or before order date
store_rows = {}
with open(inp / 'store_directory.csv', newline='') as f:
    for row in csv.DictReader(f):
        eff = date.fromisoformat(row['effective_from'])
        if eff <= order_date:
            store_rows.setdefault(row['store_id'], []).append((eff, row))
store_eff = {}
for sid, rows in store_rows.items():
    rows.sort(key=lambda x: x[0])
    store_eff[sid] = rows[-1][1]

# Tax jurisdictions
tax_by_place = {}
with open(inp / 'tax_jurisdictions.csv', newline='') as f:
    for row in csv.DictReader(f):
        tax_by_place[(row['city'], row['state'])] = Decimal(row['combined_sales_tax_pct'])

# Notices: simple parse for the explicit notices present
notice_cutoff = {}
notice_paused = set()
notice_text = (inp / 'store_notices.md').read_text()
for line in notice_text.splitlines():
    m = re.search(r'\(ST-\d+\)', line)
    if not m:
        continue
    sid = m.group(0).strip('()')
    if 'collection' in line and '16:00' in line:
        notice_cutoff[(sid, 'PICKUP')] = time(16, 0)
    if 'delivery' in line and 'paused' in line:
        notice_paused.add((sid, 'DELIVERY'))

# Stock ledger
ledger = []
with open(inp / 'stock_ledger.csv', newline='') as f:
    for row in csv.DictReader(f):
        ledger.append(row)

def parse_length_ft(s):
    s = s.strip()
    if s.endswith('ft'):
        return Decimal(s[:-2].strip())
    if s.endswith('m'):
        return Decimal(s[:-1].strip()) * Decimal('3.28084')
    raise ValueError(f'Cannot parse length: {s}')

def fit_reason(sku):
    cord = catalogue[sku]
    if cord['connector'].strip() != 'C7':
        return 'FIT_CONNECTOR'
    if cord['polarized'].strip().upper() != 'N':
        return 'FIT_POLARIZED'
    length_ft = parse_length_ft(cord['length'])
    awg = int(cord['conductor_awg'])
    if length_ft <= Decimal('6'):
        gauge_ok = True
    elif length_ft <= Decimal('15'):
        gauge_ok = awg <= 18
    else:
        gauge_ok = awg <= 16
    if not gauge_ok:
        return 'FIT_GAUGE'
    if length_ft < supplied_length_ft or length_ft > max_length_ft:
        return 'FIT_LENGTH'
    return 'NONE'

def item_match(item_code, sku):
    cord = catalogue[sku]
    return item_code.strip().lower() in (sku.lower(), cord['supplier_part'].lower())

def effective_stock(store_id, sku, order_local):
    opening_qty = Decimal('0')
    opening_dt = None
    for row in ledger:
        if row['store_id'].strip().lower() != store_id.lower():
            continue
        if not item_match(row['item_code'], sku):
            continue
        if row['event'].strip().upper() == 'OPENING' and datetime.fromisoformat(row['posted_local']).date() == order_date:
            dt = datetime.fromisoformat(row['posted_local'])
            if opening_dt is None or dt > opening_dt:
                opening_dt = dt
                opening_qty = Decimal(row['qty'])
    stock = opening_qty
    for row in ledger:
        if row['store_id'].strip().lower() != store_id.lower():
            continue
        if not item_match(row['item_code'], sku):
            continue
        evt = row['event'].strip().upper()
        dt = datetime.fromisoformat(row['posted_local'])
        if dt.date() != order_date:
            continue
        if evt == 'OPENING':
            continue
        if opening_dt is not None and dt <= opening_dt:
            continue
        if dt <= order_local:
            if evt in ('OPENING', 'RECEIPT', 'VOID'):
                stock += Decimal(row['qty'])
            elif evt in ('SALE', 'HOLD', 'TRANSFER_OUT'):
                stock -= Decimal(row['qty'])
    return stock

def store_order_local(store):
    return order_dt.astimezone(ZoneInfo(store['timezone'])).replace(tzinfo=None)

def cutoff_time(store_id, method):
    return notice_cutoff.get((store_id, method), time(15, 0))

def ready_aware(store, method, order_local):
    tz = ZoneInfo(store['timezone'])
    order_aware = order_local.replace(tzinfo=tz)
    if method == 'PICKUP':
        return order_aware + timedelta(hours=2)
    return datetime.combine(order_aware.date(), time(20, 0), tzinfo=tz)

def landed_cost(store, sku, method):
    cord = catalogue[sku]
    price = Decimal(cord['price_usd'])
    if method == 'PICKUP':
        rate = Decimal(store['sales_tax_pct'])
    else:
        rate = tax_by_place[(delivery_city, delivery_state)]
    taxed = (price * (Decimal('1') + rate / Decimal('100'))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return taxed + (delivery_fee if method == 'DELIVERY' else Decimal('0'))

