eligible = []
ready_map = {}
distance_map = {}
landed_map = {}

for oid in offer_ids:
    offer = offers[oid]
    store_id = offer['store_id']
    sku = offer['sku']
    method = offer['method']
    store = store_eff[store_id]
    order_local = store_order_local(store)
    reason = fit_reason(sku)
    stock = effective_stock(store_id, sku, order_local)
